     1	// GGX area light approximation from Horizon Zero Dawn
     2	float GetNoHSquared(float radiusTan, float NoL, float NoV, float VoL) {
     3	    float radiusCos = 1.0 / sqrt(1.0 + radiusTan * radiusTan);
     4	
     5	    float RoL = 2.0 * NoL * NoV - VoL;
     6	    if (RoL >= radiusCos)
     7	        return 1.0;
     8	
     9	    float rOverLengthT = radiusCos * radiusTan / sqrt(1.0 - RoL * RoL);
    10	    float NoTr = rOverLengthT * (NoV - RoL * NoL);
    11	    float VoTr = rOverLengthT * (2.0 * NoV * NoV - 1.0 - RoL * VoL);
    12	
    13	    float triple = sqrt(clamp(1.0 - NoL * NoL - NoV * NoV - VoL * VoL + 2.0 * NoL * NoV * VoL, 0.0, 1.0));
    14	
    15	    float NoBr = rOverLengthT * triple, VoBr = rOverLengthT * (2.0 * triple * NoV);
    16	    float NoLVTr = NoL * radiusCos + NoV + NoTr, VoLVTr = VoL * radiusCos + 1.0 + VoTr;
    17	    float p = NoBr * VoLVTr, q = NoLVTr * VoLVTr, s = VoBr * NoLVTr;
    18	    float xNum = q * (-0.5 * p + 0.25 * VoBr * NoLVTr);
    19	    float xDenom = p * p + s * ((s - 2.0 * p)) + NoLVTr * ((NoL * radiusCos + NoV) * VoLVTr * VoLVTr +
    20	                   q * (-0.5 * (VoLVTr + VoL * radiusCos) - 0.5));
    21	    float twoX1 = 2.0 * xNum / (xDenom * xDenom + xNum * xNum);
    22	    float sinTheta = twoX1 * xDenom;
    23	    float cosTheta = 1.0 - twoX1 * xNum;
    24	    NoTr = cosTheta * NoTr + sinTheta * NoBr;
    25	    VoTr = cosTheta * VoTr + sinTheta * VoBr;
    26	
    27	    float newNoL = NoL * radiusCos + NoTr;
    28	    float newVoL = VoL * radiusCos + VoTr;
    29	    float NoH = NoV + newNoL;
    30	    float HoH = 2.0 * newVoL + 2.0;
    31	    return clamp(NoH * NoH / HoH, 0.0, 1.0);
    32	}
