    34	float GGX(vec3 normalM, vec3 viewPos, vec3 lightVec, float NdotLmax0, float smoothnessG) {
    35	    smoothnessG = sqrt1(smoothnessG * 0.9 + 0.1);
    36	    float roughnessP = (1.35 - smoothnessG);
    37	    float roughness = pow2(pow2(roughnessP));
    38	
    39	    vec3 halfVec = normalize(lightVec - viewPos);
    40	
    41	    float dotLH = clamp(dot(halfVec, lightVec), 0.0, 1.0);
    42	    float dotNV = dot(normalM, -viewPos);
    43	
    44	    #if WATER_REFLECT_QUALITY >= 2
    45	        float dotNH = GetNoHSquared(0.01, NdotLmax0, dotNV, dot(-viewPos, lightVec));
    46	    #else
    47	        float dotNH = pow2(min1(2.0 * NdotLmax0 * dotNV * length(halfVec) - dot(-viewPos, lightVec)));
    48	    #endif
    49	
    50	    float denom = dotNH * roughness - dotNH + 1.0;
    51	    float D = roughness / (3.141592653589793 * pow2(denom));
    52	    float f0 = 0.05;
    53	    float F = exp2((-5.55473 * dotLH - 6.98316) * dotLH) * (1.0 - f0) + f0;
